import dotenv from 'dotenv';
import path from 'path';
import fs from 'fs';

dotenv.config();

function required(key: string): string {
  const value = process.env[key];
  if (!value) {
    throw new Error(`Missing required environment variable: ${key}`);
  }
  return value;
}

function optional(key: string, fallback: string): string {
  return process.env[key] || fallback;
}

// Fallback deployed contract addresses (generated by blockchain deploy.ts)
let fallbackAddresses = {
  emergencyLedger: '',
  responderRegistry: '',
  chainId: 31337,
};
try {
  const addressesPath = path.join(__dirname, '../contracts/addresses.json');
  if (fs.existsSync(addressesPath)) {
    const raw = JSON.parse(fs.readFileSync(addressesPath, 'utf8'));
    fallbackAddresses.emergencyLedger = raw.emergencyLedger || '';
    fallbackAddresses.responderRegistry = raw.responderRegistry || '';
    if (raw.chainId) fallbackAddresses.chainId = Number(raw.chainId);
  }
} catch (_) {}

export const config = {
  port: parseInt(optional('PORT', '3000'), 10),
  nodeEnv: optional('NODE_ENV', 'development'),
  corsOrigin: optional('CORS_ORIGIN', '*'),

  mongodb: {
    uri: required('MONGODB_URI'),
  },

  jwt: {
    secret: required('JWT_SECRET'),
    expiresIn: optional('JWT_EXPIRES_IN', '24h'),
  },

  matching: {
    initialRadiusM: parseInt(optional('MATCHING_INITIAL_RADIUS_M', '500'), 10),
    secondRadiusM: parseInt(optional('MATCHING_SECOND_RADIUS_M', '1000'), 10),
    maxRadiusM: parseInt(optional('MATCHING_MAX_RADIUS_M', '3000'), 10),
    locationFreshnessMin: parseInt(optional('MATCHING_LOCATION_FRESHNESS_MIN', '5'), 10),
    expansionDelayMs: parseInt(optional('MATCHING_EXPANSION_DELAY_MS', '10000'), 10),
  },

  blockchain: {
    rpcUrl: optional('BLOCKCHAIN_RPC_URL', ''),
    privateKey: optional('BLOCKCHAIN_PRIVATE_KEY', ''),
    emergencyLedgerAddress: optional(
      'BLOCKCHAIN_EMERGENCY_LEDGER_ADDRESS',
      fallbackAddresses.emergencyLedger,
    ),
    responderRegistryAddress: optional(
      'BLOCKCHAIN_RESPONDER_REGISTRY_ADDRESS',
      fallbackAddresses.responderRegistry,
    ),
    reputationAddress: optional('BLOCKCHAIN_REPUTATION_ADDRESS', ''),
    chainId: parseInt(
      optional('BLOCKCHAIN_CHAIN_ID', String(fallbackAddresses.chainId)),
      10,
    ),
  },

  rateLimit: {
    windowMs: parseInt(optional('RATE_LIMIT_WINDOW_MS', '900000'), 10),
    maxRequests: parseInt(optional('RATE_LIMIT_MAX_REQUESTS', '100'), 10),
  },

  get isBlockchainConfigured(): boolean {
    return !!(
      this.blockchain.rpcUrl &&
      this.blockchain.privateKey &&
      this.blockchain.emergencyLedgerAddress
    );
  },

  get blockchainMode(): 'on-chain' | 'mvp-simulation' {
    return this.isBlockchainConfigured ? 'on-chain' : 'mvp-simulation';
  },
} as const;
